const raw = String(
  $json.choices?.[0]?.message?.content ||
  $json.candidates?.[0]?.content?.parts?.[0]?.text ||
  '{}'
).replace(/```json|```/g, '').trim();

let parsed = null;
try {
  parsed = JSON.parse(raw);
} catch (err) {
  parsed = null;
}

if (!parsed || typeof parsed !== 'object') {
  return {
    json: {
      status: 'FAIL',
      has_discount_offer: false,
      blockers: [{
        category: 'qa_engine_error',
        issue: 'AI QA output could not be parsed cleanly',
        fix: 'Re-run Pre-Flight QA or check API credentials before scheduling.'
      }],
      warnings: []
    }
  };
}

return {
  json: {
    status: parsed.status || 'FAIL',
    has_discount_offer: Boolean(parsed.has_discount_offer),
    blockers: Array.isArray(parsed.blockers) ? parsed.blockers : [],
    warnings: Array.isArray(parsed.warnings) ? parsed.warnings : []
  }
};

